using UnityEngine;

public class Player : MonoBehaviour
{
    void Awake()
    {
        if (GameManager.Instance != null)
            Debug.Log("Player: GameManager found!");
        else
            Debug.LogError("Player: GameManager is NULL!");
    }
}

